    if rt=='Task':
        if r['status']=='requested':
            return f"{t} REQUEST {i}: {r['code']['coding'][0]['code']} focus={r['focus']['reference']} :: {r['description']}"
        return f"{t} ITEM {i}: {r.get('businessStatus')}"
    return f"{t} {rt} {i}"

pids = sys.argv[1:] if len(sys.argv)>1 else sorted(pats)
