MON={m:i+1 for i,m in enumerate(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])}
def parse(s):
    s=s.strip()
    m=re.match(r'^(\d{4})-(\d{2})-(\d{2})$',s)
    if m: return datetime.date(*map(int,m.groups()))
    m=re.match(r'^(\d{1,2})/(\d{1,2})/(\d{2,4})$',s)
    if m:
        a,b,c=m.groups(); c=int(c); c=c+2000 if c<100 else c
        return datetime.date(c,int(a),int(b))
    m=re.match(r'^([A-Z][a-z]{2})\w*\.?\s+(\d{1,2}),?\s+(\d{4})$',s)
    if m: return datetime.date(int(m.group(3)),MON[m.group(1)],int(m.group(2)))
    m=re.match(r'^(\d{1,2})-(\d{1,2})-(\d{4})$',s)
    if m: return datetime.date(int(m.group(3)),int(m.group(1)),int(m.group(2)))
    return None
pat=re.compile(r'(?:RPR nonreactive here|last RPR|neg RPR|Last syphilis screen at this clinic|RPR nonreactive)\s*([A-Za-z0-9/,\- ]{6,20}?)(?:\s+was nonreactive|\s+at this clinic|[.;,]|$)')
