    m=re.match(r'^([A-Z][a-z]{2})\w*\.?\s+(\d{1,2}),?\s+(\d{4})$',s)
    if m: return datetime.date(int(m.group(3)),MON[m.group(1)],int(m.group(2)))
    m=re.match(r'^(\d{1,2})-(\d{1,2})-(\d{4})$',s)
    if m: return datetime.date(int(m.group(3)),int(m.group(1)),int(m.group(2)))
